import json
from pathlib import Path

import numpy as np
import jax
import jax.numpy as jnp


ROOT = Path(__file__).resolve().parent


def load_problem(path: Path):
    with path.open("r", encoding="utf-8") as f:
        return json.load(f)


def task_basic_reduce(input_path: Path):
    x = jnp.array(np.load(input_path))
    return jnp.mean(x, axis=1)


def task_map_square(input_path: Path):
    x = jnp.array(np.load(input_path))
    square_row = jax.vmap(lambda row: row ** 2)
    return square_row(x)


def task_grad_logistic(input_path: Path):
    data = np.load(input_path)
    x = jnp.array(data["x"])
    y = jnp.array(data["y"])
    w = jnp.array(data["w"])

    def loss_fn(w_param):
        logits = jnp.dot(x, w_param)
        return jnp.mean(jnp.logaddexp(0.0, -y * logits))

    grad_fn = jax.grad(loss_fn)
    return grad_fn(w)


def task_scan_rnn(input_path: Path):
    data = np.load(input_path)
    seq = jnp.array(data["seq"])
    h0 = jnp.array(data["init"])
    Wx = jnp.array(data["Wx"])
    Wh = jnp.array(data["Wh"])
    b = jnp.array(data["b"])

    def step(h, x_t):
        h_next = jnp.tanh(jnp.dot(x_t, Wx) + jnp.dot(h, Wh) + b)
        return h_next, h_next

    _, h_seq = jax.lax.scan(step, h0, seq)
    return h_seq


def task_jit_mlp(input_path: Path):
    data = np.load(input_path)
    X = jnp.array(data["X"])
    W1 = jnp.array(data["W1"])
    b1 = jnp.array(data["b1"])
    W2 = jnp.array(data["W2"])
    b2 = jnp.array(data["b2"])

    def mlp_forward(x):
        h = jnp.maximum(0.0, jnp.dot(x, W1) + b1)
        return jnp.dot(h, W2) + b2

    mlp_forward_jit = jax.jit(mlp_forward)
    return mlp_forward_jit(X)


def main():
    problems = load_problem(ROOT / "problem.json")
    for problem in problems:
        input_path = ROOT / problem["input"]
        output_path = ROOT / problem["output"]
        output_path.parent.mkdir(parents=True, exist_ok=True)

        desc = problem["description"].lower()
        task_id = problem.get("id", "")

        if task_id == "basic_reduce" or "mean" in desc:
            result = task_basic_reduce(input_path)
        elif task_id == "map_square" or "square" in desc:
            result = task_map_square(input_path)
        elif task_id == "grad_logistic" or "logistic" in desc:
            result = task_grad_logistic(input_path)
        elif task_id == "scan_rnn" or "rnn" in desc:
            result = task_scan_rnn(input_path)
        elif task_id == "jit_mlp" or "mlp" in desc:
            result = task_jit_mlp(input_path)
        else:
            raise ValueError(f"Unknown task: {problem}")

        np.save(output_path, np.asarray(result))


if __name__ == "__main__":
    main()
